(window.webpackJsonp=window.webpackJsonp||[]).push([[99],{538:function(t,s,v){"use strict";v.r(s);var _=v(11),e=Object(_.a)({},(function(){var t=this,s=t.$createElement,v=t._self._c||s;return v("ContentSlotsDistributor",{attrs:{"slot-key":t.$parent.slotKey}},[v("p",[v("font",{attrs:{size:"5"}},[t._v("摘要：")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("1、自从进入应许之地，一直到耶稣出现，从来没有一个犹太人得了麻风病被治愈过，因此犹太拉比们会把医治大麻风上升为一个“弥撒亚神迹”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("2、无论是对耶稣而言，还是对在场的其他人而言，耶稣说‘你的罪赦了’，是更难的，说“你起来行走”是更容易的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("3、耶稣之所以会舍易求难，就是要让他们知道，弥赛亚在地上是有赦罪的权柄的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("4、在神所创造的宇宙中，人与神的关系是最根本、最重要的关系；因为神控制着一切，只有这个关系对了，你与神所创造的其他的受造物的关系才可能对。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("5、与神的关系错了，即使你没有长大麻风、没有瘫痪、没有生病，你与病毒、或细菌、或与其他一切受造物的关系也不是在神起初所设计的那个秩序当中，因此其实你与他们的关系也是扭曲的，并且这种扭曲最终会极大地伤害你。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("6、只有你与神的关系对了，你与其他的受造物的关系才会是对的，即使你长大麻风，即使瘫痪，即使你灾病缠身、即使你缺衣少食、即使你妻离子散，也是对的。因为在这些时候，这些其他受造物也是在为你服务。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("7、你们一定听过这个说法：画一个十字架，有垂直关系，有水平关系，然后他告诉你，你的垂直关系、也就是你与神的关系好了，你的水平关系，也就是与人的关系自然就好了。这些都是瞎扯。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("8、如果一个人客观上犯了罪、得罪了神，但他主观上认为没有，或者没什么大不了的，他就不会对自己的罪感到恶心，他也不会到耶稣那里寻求赦罪，因为耶稣对他而言是没有意义的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("9、一个客观的善行，必须同时符合这三个条件：目的上为了荣耀神；心态上谦卑；行为上公义，并且如果你这个行为针对某个人，那么是要为了他的益处。否则就不是善，就是罪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("10、真正的基督徒，客观上有罪，和所有人一样；主观上却会承认他们有罪、会对自己的罪感到厌恶、沮丧。所以他们会来到耶稣面前，因为他有赦罪的权柄！他对他们有意义！这些是耶稣所召的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们平安。今天我们继续来看路加福音5:12~32节。我们一起来读。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("一、弥赛亚的神迹")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们首先从第17节开始讲。刚才我们已经读了，17节~26节这里记载了耶稣医治一个瘫子的事件。我们从马可福音的平行经文知道，这件事情发生在迦百农。迦百农位于加利利湖的西北岸，距离耶路撒冷的直线距离约有177公里，这是一条比较近的路。但在耶稣时代，因为走这条路必须要穿过撒玛利亚地区，所以如果一个犹太人要从耶路撒冷到迦百农，他们是不会走这条路的，而是会先向东到达约旦河，然后沿着约旦河向北行进，经过耶利哥，再向西渡河进入加利利地区，最终到达迦百农。这条路线较长，大约有约200公里，需要7~8天左右的时间。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("第17节这里描述了耶稣医治瘫子的事件中的见证人。这里说有法利赛人和教法师：他们是从加利利各乡村和犹太并耶路撒冷来的。加利利我们很熟悉了，迦百农就在加利利，这是耶稣主要传道的场所，位于撒玛利亚地区的北边。耶路撒冷相对于迦百农的地理位置刚才我们也已经说过了。而这里提到的“犹太地区”，是位于撒玛利亚的南边，包括了耶路撒冷在内的一片区域。当时在巴勒斯坦的犹太人，主要就聚集在加利利和犹太。所以这里提到这些在现场的法利赛人和教法师来自于加利利、犹太、耶路撒冷，就意味着，整个犹太地区都派出了法利赛人和教法师来见耶稣。刚才我们说了，从耶路撒冷到迦百农就得7~8天的路程，而有些犹太地区的法利赛人可能住的更远，那他们到耶稣那里就得花更长的时间。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在这里我们就遇到一个问题：为什么全犹太地区的宗教代表都来见耶稣？为什么这些人要跋山涉水来到耶稣这里？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("要回答这个问题，我们需要了解一些历史背景。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家知道，当时的犹太人都在盼望着旧约圣经中所预言的弥赛亚的到来，把他们从罗马统治的铁蹄下拯救出来，恢复大卫、所罗门王朝的荣耀。在这样的氛围下，就会不时有人出来声称自己就是弥撒亚，鼓动群众，然后不时在犹太人中形成一场“弥赛亚运动”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当时的犹太公会就制定了一种包含两个阶段的调查方案来对出现的各种“弥赛亚运动”进行调查。第一个阶段是由整个犹太地区的宗教代表来进行观察，看这个“弥赛亚”做了什么、说了什么。这个阶段，他们是不允许发问的。在这之后，他们会向耶路撒冷的公会进行汇报，以判断这个弥赛亚运动是否真的特殊或者重要。如果他们认为是无关紧要的，那么这个事情就被搁置下来，否则的话，就会进入到调查的第二个阶段。在这个阶段，他们会对被视为弥赛亚的个人或运动的成员进行发问。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而路加福音5:17节这里记载的情况，就是他们在进行第一阶段的调查。这样我们也就同时理解了，当耶稣对瘫子说你的罪被赦了（5：20节），他们为什么只是在心里议论（5:21~22）。因为现在是第一个阶段，他们是不能发问的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("现在我们了解了这个背景：犹太公会已经启动了对这场弥赛亚运动的调查。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就把我们带入到下一个问题：他们为什么会启动这个调查？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("现在让我们来看路加福音5:12~16节。这里记载耶稣医治了一位患大麻风病的人，并在14节嘱咐他，“你切不可告诉人，只要去把身体给祭司看，又要为你得了洁净，照摩西所吩咐的献上礼物，对众人作证据。”当这个麻风病人去到耶路撒冷的祭司那里，祭司会按照利未记14:1~32节的规定，查看他的病情，宣告他为洁净。而他也要按照那里的规定献上祭物。我们一起来翻到利未记，看看那里是怎么写的。我们一起来读一下。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看，这就是这个被耶稣所洁净的麻风病人，按照耶稣的吩咐去到祭司那里，会经历的事情。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但大家知道吗？当他出现在耶路撒冷、出现在祭司面前，告诉他们我的大麻风已经痊愈了，请你们按照摩西律法的规定来查看我，完成律法中记载的各种仪式的时候，这些祭司会感到震惊！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("为什么？因为利未记14章1~32节这里的规定，自犹太人进入应许之地开始，就从来没有被执行过。也就是说，从来没有一个犹太人得了麻风病被治愈过，然后去找祭司按照利未记14章来走过这个流程！在以色列进入应许之地一直到当时大约1400年的时间里面，从来没有过！我们在讲路加福音第4章的时候，提到过以利沙曾经医治过乃缦的大麻风，但乃缦不是以色列人，他被治好以后也就走了，不会去按照利未记14章的流程走一遍。而以色列人中，从来没有人被医治过！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我怎么知道的？这是研究犹太历史、研究犹太教的学者们得出的结论。也正是因为这样，当时的犹太拉比才会把“医治大麻风”，归类为是“弥赛亚神迹”。那个时候有不少人都能行神迹，但犹太人特别把某些神迹归类为“弥赛亚神迹”，用以判断是否是他们的弥赛亚来了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来看路加福音第7章18~22节。这里记载约翰在监狱里面，打发他的门徒去问耶稣，你是不是我们在等候的那一位呢？也就是说，他让耶稣明确告诉他，你就是我们在盼望的那位弥撒亚吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣是如何回答的呢？7:22节，他说“你们去，把所看见所听见的告诉约翰，就是瞎子看见，瘸子行走，长大麻风的洁净，聋子听见，死人复活，穷人有福音传给他们。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣在这里引述了他行的好几个神迹，来向施洗约翰证明自己就是弥赛亚。如果我们去看先知书就会看到，瞎子看见，瘸子行走，聋子听见，死人复活，这些都是先知所预言的弥赛亚来复兴以色列的时候会发生的事情。唯有“长大麻风的洁净”，你在先知书里是找不到的，在旧约圣经其他地方也找不到。旧约中从来没有把大麻风得医治与弥赛亚关联起来过。那为什么耶稣要提到这个神迹来向施洗约翰证明自己是弥赛亚？就是因为这是当时的犹太拉比们所界定的“弥赛亚神迹”。其实很自然，如果这种大麻风被医治的事常常发生，犹太拉比们当然就不会把它放到那么高的位置。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以耶稣医治了这个麻风病人，不仅仅是在行一个神迹，而是在行一个“弥赛亚神迹”；耶稣嘱咐他去祭司那里让他们查看、献上摩西所规定的礼物，他也不仅仅是在吩咐他按照程序走一遍，不仅仅是表达耶稣自己对律法的尊重，而是在向犹太的宗教领袖们传递一个信号：你们的弥赛亚来了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("犹太的公会显然是收到了这个信号。他们不仅收到了，并且还知道了行这个神迹的人是谁。而且不仅他们知道了，有很多人都知道了。因为这个被洁净的人违背了耶稣的嘱咐，把谁洁净了他大肆宣扬，正如5：15节说“耶稣的名声越发传扬出去”。除了引起犹太公会的注意，当然也有极多的人被吸引来，要听他讲道，并且指望耶稣医治他们的病。因为这些群众也当然知道，医治大麻风是他们的教法师们所说的弥赛亚神迹。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("二、弥赛亚的权柄")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣知道，犹太公会会开始启动对他的调查，而一场“弥赛亚运动”也正在酝酿当中。这种运动不是他想看到的，所以第16节说面对着汹涌而来的追随者，他却退到旷野去祷告。我们只能猜测他会祷告些什么：也许他会为自己能坚守使命而祷告；也许他还会为犹太的宗教领袖们、犹太的群众们祷告，祈求神帮助他们能正确认识到弥赛亚的身份是什么、使命是什么，因而能认出他就是他们的弥赛亚、知道跟随他意味着什么。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("当时的犹太人（包括现在的犹太教）普遍对弥赛亚的认识是：这是一位像摩西、大卫一样的人物。当然，他比摩西、大卫有能力得多、荣耀得多、所建立的功业也大得多。他会把以色列人从罗马的铁蹄下拯救出来，并且会在全世界——对当时的犹太人而言，全世界就意味着罗马帝国——建立一个以犹太民族为中心的神权国家，统治万邦直到永远。所以在他们的认知下，弥赛亚是一位政治的君王、荣耀的领袖，因此跟着他，就将得到现世当中的荣耀和祝福，而他绝不可能承受羞辱、失败；他与神有着特殊的密切关系，是神在人间的代表，但他也绝不是神本身。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("带着这样的对弥赛亚的认识，那个全身都长着大麻风的人，确信耶稣有洁净他的能力，因此俯伏在地，说“主若肯，必能叫我洁净了”（路5:12）。我们并不清楚他是如何对耶稣产生这么大的信心的——我们刚才说了，在犹太人的观念中，洁净大麻风是弥赛亚才能行的神迹——或许是他听说了太多耶稣在加利利行的各种神迹，也听说了耶稣在加利利各会堂所宣告的，他自己就是先知以赛亚所预言的那位有圣灵的人，那位受膏者（受膏者就是弥赛亚的意思）（耶稣在加利利会堂里面传讲的就是这个信息，我们在分享路加福音第4章的时候，已经看到过了），因此已经在心里认定他就是他们在期盼的那一位。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("也是带着这样的对弥赛亚的认识，人潮从四面八方聚集到耶稣这里，要听他讲道，也指望自己的疾病得到他的医治（路5:15）。他们心目中那个荣耀的弥赛亚、大能的弥赛亚、祝福的弥赛亚，当然有能力来医治他们的疾病。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("也是带着这样的对弥赛亚的认识，那个瘫子和他的朋友来寻求耶稣的医治（路5：18）。因为既然这位受膏者、神的代表、弥赛亚能洁净大麻风病人，那他当然也能医治瘫子，正如以赛亚预言弥赛亚到来的时候的情形：“那时，瞎子的眼必睁开，聋子的耳必开通；那时，瘸子必跳跃像鹿，哑巴的舌头必能歌唱。”（以赛亚书35:5~6）而且他们的信心还很大。在路加福音5：18~20节说，因为人多，他们没办法到耶稣面前，于是就上了房顶，从瓦间把他们的瘫子朋友连褥子一起垂到当中，来到耶稣面前。只有非常确信耶稣有这样医治的能力，他们才会做出这种事情来。第21节也肯定了这一点，这里说耶稣看到了他们的“信心”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但是这一次，面对他们的信心，耶稣不是像他对待那麻风病人一样，直接给他洁净了；也不是像他对待那些从四面八方涌来寻求他医治的百姓，直接就给他们医治了（在16节虽然说耶稣面对他们，他退到旷野去祷告；但在第17节最后我们可以看到，耶稣实际上还是医治了他们的疾病的）。这一次，他见到这个瘫子和他朋友们的信心，他没有直接让瘫子起来行走，而是对他说：“你的罪赦了”。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他的这句话引起了在场的文士和法利赛人心里的嘀咕：“这说僭妄话的是谁呢？除了神以外，谁能赦罪呢？”（路5：21）他们的逻辑很简单：只有神才能赦罪，而弥赛亚不会是神本身，所以弥赛亚是没有权柄去赦免人的罪的；但这个人却说自己能赦罪，把自己与神同等，这是亵渎神，弥赛亚当然不会亵渎神；所以这个人，不会是弥赛亚。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但很显然，耶稣这样做，他是故意的。第23节，他问他们“或说‘你的罪赦了’，或说‘你起来行走’，哪一样容易呢？”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我知道大家可能会觉得说“你的罪赦了”容易一些吧？因为说人的罪赦了，不需要验证，而说你起来行走，是能立即就被检验的。那是对你而言，不是对耶稣。耶稣是不怕被立即检验的。他自己很清楚自己的能力是怎么样的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家想一想如果他不说这句话，而是像对待那个麻风病人一样，直接让这个瘫子起来行走，会发生什么？在场所有的人都会高兴，包括那些法利赛人和教法师。因为耶稣并不与他们所心目中所想象的弥赛亚的形象冲突。大家都会喜欢他。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但现在，耶稣却先说“你的罪赦了”。这就挑战了人们对弥赛亚的认知，那就有可能会激起人们的敌意来。我们也看到了，那些法利赛人和文士对耶稣的敌意，确实被激起来了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以“或说‘你的罪赦了’，或说‘你起来行走’，哪一样容易呢？”这对你而言，面对的是一个你的话能不能被立即验证的问题；但对耶稣而言，面对的是他将被大家所欢迎，还是被大家所抵挡的问题。所以对耶稣来说，当然是说“你的罪赦了”，是更难的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("不仅对耶稣更难，对当时的听众而言也是更难的。因为他们不得不自觉或不自觉地去重新检验自己对弥赛亚的认识，从而判断耶稣到底是亵渎者还是真可能是弥赛亚。这是不容易的，尤其是对那些已经形成根深蒂固观念的法利赛人和文士。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以无论是对耶稣而言，还是对在场的其他人而言，耶稣说‘你的罪赦了’，是更难的，说“你起来行走”是更容易的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那为什么耶稣要舍易求难？我们来看第24节，大家注意这个“但”字，这表明耶稣他是故意的。他这么做的目的是“叫你们知道，人子在地上有赦罪的权柄”。“人子”这个概念在旧约当中出现过好几次，比较重要的是诗篇80以及但以理书7章，这些都是有关弥赛亚的经文。耶稣告诉他们，我之所以会舍易求难，我之所以情愿引起你们的敌意我也要这么做，就是要让你们知道，弥赛亚在地上是有赦罪的权柄的。而这个瘫子，他相信我，我就把他的罪赦免了。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("接下来，耶稣才做那个对他而言容易的事情，医治了这个瘫子。当众人看到这个瘫子起来的时候反应是什么呢？第26节说他们都被震惊了，并且“归荣耀与神”。他们确认，这是神的作为；既然如此，那么耶稣就不是亵渎者；既然如此，那么他说他有赦罪的权柄，这当然也就是没问题的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("26节这里的“众人”，我想并不包括那些在场的法利赛人和教法师，而是那些没什么文化、“神学”根基不扎实的无知群众。他们可能搞不清楚弥赛亚到底能不能赦罪这个神学问题，只是看到这个“非常之事”，就被深深震撼，对耶稣毫无质疑。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而耶稣行的这个神迹，却会难坏那些“神学根基扎实”的法利赛人和教法师。因为耶稣宣告他可以赦罪，他们已经在内心对他产生了敌意、倾向于否定他是弥赛亚、认定他是个亵渎者。那么现在他们需要思考：一个亵渎者，能够行这样的神迹吗？要如何解释这个事情？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这个问题当然要留给他们离开后自己去寻找答案，他们要么调整自己对弥赛亚的神学认知，要么把耶稣行的神迹解释为是游方术士的迷惑人的法术。很遗憾的是，从历史上看，大部分的法利赛人，都选择了后者。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们再来看第24节后面，他是如何医治这个瘫子的。耶稣对他说：“我吩咐你，起来，拿你的褥子回家去吧”。然后那个人就立刻起来了。大家看到了吗？这一次，他甚至没有像医治大麻风那次伸出手来，而只是吩咐瘫子起来，瘫子就得到了医治。在医治麻风病人的时候，耶稣有意要伸出手去摸他，他不是非这样做不可，这是显明弥赛亚的怜悯（我们都知道那个时候大麻风是大家唯恐避之不及的病）；在医治瘫子的时候，他不需要做什么动作，只需要用命令，这是显明弥赛亚的权柄。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以在医治瘫子这件事情中，耶稣既向人们显明了他有赦罪的权柄，又显明了他有医治的权柄。这很正常，连赦罪都有权柄的人，当然也对疾病有权柄。因为罪是人与神的关系发生了错误，而疾病只是人与自然界的关系发生了错误。你违背了神的律法，就是颠倒了你与神之间的位置，这就是犯罪；而长大麻风，无非就是某种细菌在你皮肤上多了，你抵御不了；瘫痪，无非就是某种病毒入侵了你的神经系统，导致你的大脑没法控制你的双腿。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("在这样一个神所创造的宇宙中，当然是人与神的关系是最根本、最重要的关系；因为神控制着一切，只有这个关系对了，你与神所创造的其他的受造物的关系才可能对。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以如果弥赛亚能把这个关系给就纠正过来，当然去纠正人与物的关系、人与人的关系，也就不在话下了。反过来说，如果弥赛亚只能去解决疾病，只能够去对付罗马人，只能去赶鬼，那当然也比较厉害，但其实并不是非常厉害，因为这些都是治标不治本的。而耶稣首先用他的权柄赦免这个瘫子的罪，解决他的根本问题；然后用他的权柄医治了他。标本兼治。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我再强调一次，只有你与神的关系对了，你与神所创造的其他的受造物的关系才会是对的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("与神的关系错了，即使你没有长大麻风，即使你没有瘫痪，即使你没有生病，你与病毒、或细菌、或与其他一切受造物的关系也不是在神起初所设计的那个秩序当中，因此其实你与他们的关系也是扭曲的，并且这种扭曲最终会极大地伤害你。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来翻到路加福音10章，看一看第13~14节是怎么说的。“哥拉汛哪，你有祸了！伯赛大啊，你有祸了！因为在你们中间所行的异能，若行在推罗、西顿，他们早已披麻蒙灰、坐在地上悔改了。当审判的日子，推罗、西顿所受的比你们还容易受呢！”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家看到了吗？耶稣在哥拉汛、伯赛大行了很多神迹，其实也就是通过超自然的方式供应给那里的人他们需要的东西，或者我们再抽象一点说，是通过超自然的方式，校正了人与其他受造物的关系。这个被校正之后的关系是什么？就是其他受造物为人服务，而不是对人造成伤害。圣经里面记载，耶稣在这些地方医治了瞎眼的、行了五饼二鱼的神迹。但是这些地方的人却没有悔改。也就是说，他们与神的关系没有被校正过来。这导致的结果是什么？耶稣说，当审判的日子，推罗、西顿所受的比他们还容易受呢！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是我刚才说的，你与神的关系是错了，即使你与其他受造物的关系暂时看上去对的——无病无灾、丰衣足食、夫妻恩爱、父慈子孝，但也是扭曲的，并且这种扭曲最终会极大地伤害你。因为你与其他受造物这种暂时看上去对的关系，也是神安排来，目的是让你与他的关系能被修正过来。如果你拒绝，那么当审判的日子，你会受更重的审判。因为神是公义的，他多给谁，就向谁多取；多托谁，就向谁多要。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("从另一个方面讲，只有你与神的关系对了，你与其他的受造物的关系才会是对的，即使你长大麻风，即使瘫痪，即使你灾病缠身、即使你缺衣少食、即使你妻离子散，也是对的。为什么这么说？还是那个道理，因为在这些时候，这些其他受造物是在为你服务。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们来看罗马书第8章28~32：“我们晓得万事都互相效力，叫爱神的人得益处，就是按他旨意被召的人。因为他预先所知道的人，就预先定下效法他儿子的模样，使他儿子在许多弟兄中做长子；预先所定下的人又召他们来，所召来的人又称他们为义，所称为义的人又叫他们得荣耀。既是这样，还有什么说的呢？神若帮助我们，谁能敌挡我们呢？神既不爱惜自己的儿子，为我们众人舍了，岂不也把万物和他一同白白地赐给我们吗？”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这里是不是说得无比清楚了？对于爱神的人——也就是与神的关系正确的人——神就驱动万事，来为他们服务，让他们得到益处。这个益处是什么？就是让他们能够效法他儿子的模样，让他们能够得着荣耀。第32说，神不仅把他的儿子赐给我们，也把万物都白白地赐给我们，让他们来为我们服务。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以如果你与神的关系对了，你与其他受造物也才会是对的。因为他们都是神给你，来为你服务的。无病无灾、丰衣足食、夫妻恩爱、父慈子孝、灾病缠身、妻离子散、缺衣少食、患难、困苦、逼迫、饥饿、赤身露体、危险、刀剑、天使、掌权的、有能的、现在的事、将来的事、高处的、低处的、别的受造之物，都是在为你服务，让你可以有神儿子的生命、让你可以得着荣耀！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是为什么，当犹太公会启动对这场弥赛亚运动第一阶段的调查，当来自犹太各地的拉比们跋山涉水聚集到迦百农，来观察这位行了洁净麻风病这一弥赛亚神迹的拿撒勒木匠的时候，耶稣看到这个瘫子的信心，他会去舍易求难，首先宣告，“你的罪赦了”。他首先要让他们知道，他有赦罪的权柄；他要让他们知道，他来所要解决的首先是那个最重要、最根本的问题，而不是那些次要的问题，什么医治麻风病、医治瘫子，什么解救他们脱离罗马的统治等等这些问题。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，那么你们是不是足够清楚，耶稣所解决的首要问题是什么？不是让你能找个姐妹，组建一个美满的婚姻；不是让你科研顺利，找到一个称心的工作；不是让你能融入教会，有一个舒服的社交圈子；也不是像有些心怀天下的知识分子所谓的“异象”，用基督教来改造中国以确保中国长治久安，这些不是异象，是意淫。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣要解决首要问题不是这些。耶稣首要解决的是你的罪的问题，是让你和神的关系正确的问题。当这个问题被解决了，神所创造的万物才会被他驱动来祝福你。而且这个祝福也不是让你家庭美满、工作称心、无病无灾，更不是什么国家富强。而是指你能效法他儿子的模样，活出他儿子的生命品质，并最终在荣耀中与神同在。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你们一定听过这个说法：画一个十字架，有垂直关系，有水平关系，然后他告诉你，你的垂直关系、也就是你与神的关系好了，你的水平关系，也就是与人的关系自然就好了。你可能也听过这样的说法：我们不要去追求国家富强，我们要去传福音，当中国大部分人都信主了，国家富强只是一个自然的副产品。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我告诉大家，这些都是瞎扯。你与神的关系正确了、好了，你与人的关系也会“正确”。但这个“正确”不一定是我们通常理解的世俗上的“好”、“美满”、“幸福”。而是什么呢？一方面你会按照神的要求来对待这个人，另一方面神也会驱动这个人，来让你得益处——就是更有他儿子的形象。怎么驱动？可能是让你们的关系变得在世俗意义上更好，也可能是变得在世俗意义上更坏。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同样，如果中国大部分人都信主了，神也会驱动万事，让这些信主的人得到益处——就是更有他儿子的形象。怎么驱动？可能是让国家富强，也可能是让国家贫困。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以，你是不是知道，耶稣最重要的权柄，是赦罪的权柄，是解决罪的权柄。正如约翰福音1:29节记载，在耶稣刚一出场，施洗约翰就说：“看哪，神的羔羊，除去世人罪孽的！”这是耶稣首先向犹太的拉比们宣示的信息，是施洗约翰首先向犹太群众们所宣誓的信息。也是神首先向今天的我们宣示的信息。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你是不是听到了这个信息？好。听到了之后，与你有什么关系？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("三、耶稣的任务")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("我们继续来看今天的经文27~32节，这里记载了耶稣呼召利未、以及耶稣在利未家坐席的事。如果我们去看马可福音2:15节的平行经文，那里说到“耶稣在利未家里坐席的时候，有好些税吏和罪人与耶稣并门徒一同坐席，因为这样的人多，他们也跟随耶稣。”从这段经文我们其实可以看到，耶稣不仅呼召了利未，他还呼召了其他的税吏和罪人，因为马可福音记载这些人也都跟随耶稣。税吏的角色我们都比较熟悉了，一方面，他们是犹太人、负责帮罗马人收税，这在当时的犹太人中被视为是叛徒；另一方面，当时罗马的税收系统是一种类似于承包制的体制，税吏只要向罗马交够所要求的，剩下的都是自己的。这样就导致税吏普遍都会通过欺压、强迫等方式进行敛财，欺压自己的同胞。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而路加福音5：30说的“罪人”，应该是指当时被犹太社会普遍认定的坏份子，很可能包括一些暴徒（当时税吏往往会雇佣暴徒来征税），甚至也许还有妓女。如果用我们今天的话说，耶稣相当于是呼召了一群半黑社会份子，并与他们一起坐席。为什么是“半黑社会”呢？因为他们的行为是被罗马政府允许的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("耶稣这个行为就这引起了法利赛人和文士的质疑。从这里我们可以了解到，犹太公会对耶稣的调查已经进入第二阶段了。刚才我们讲过，洁净麻风病人的神迹让他们启动了这个弥赛亚运动的调查，在第一阶段，他们会观察，但是不允许发问，然后向耶路撒冷公会进行汇报。如果他们认为是无关紧要的，那么这个事情就被搁置下来，否则的话，就会进入到调查的第二个阶段。在这个阶段，他们会提出问题。很显然，耶稣宣告赦罪的话以及医治瘫子的神迹让他们认为这事非同小可，于是第二阶段启动了。这就是为什么我们会经常看耶稣做什么事，同时也会有法利赛人和文士在场，对他提出质询。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他们质疑：“你们为什么和税吏并罪人一同吃喝呢？”在他们心目中，弥撒亚是圣洁的、荣耀的，不应该和税吏、恶棍、妓女们混在一起。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("而耶稣的回答延续了他在医治瘫子时候的宣告。在那里，他向法利赛人宣示自己在世上有赦罪的权柄；在这里，他向法利赛人展示，这个权柄是如何作用在世上的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("“无病的人用不着医生，有病的人才用得着。我来本不是召义人悔改，乃是召罪人悔改。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("皮肤光滑的人，不需要洁净麻风；双腿健壮的人，不需要医治瘫痪；同样，没有罪的人，不需要被赦罪。耶稣确实有赦罪的权柄，但这个权柄只对那些有罪的人才有意义。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以回到我们刚才那个问题，神向犹太人、向法利赛人、向今天的我们宣告，耶稣首要的权柄，是赦罪的权柄。你是不是听到了这个信息？好。听到了之后，与你有什么关系？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这取决于你客观上是不是有罪，以及你主观上是不是认为自己有罪，因此会对罪厌恶。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果一个人在客观上长满了疹子，他主观上却认为自己皮肤健康，他不会对满身的疹子感到厌恶，那他不会去看医生，那医生自然对他而言就没有意义；")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果一个人客观上走不了路，但他主观上认为这很正常，没什么大不了的，他不会为自己走不了路而不安，他当然也不会去看医生，因为医生对他而言也没有意义。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("同样，如果一个人客观上犯了罪、得罪了神，但他主观上认为没有，或者没什么大不了的，他就不会对自己的罪感到恶心，他也不会到耶稣那里寻求赦罪，因为耶稣对他而言是没有意义的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这就是无数不信之人的状态，这也是无数自称为基督徒的人的状态：客观上是犯罪了，主观上却认为没有。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("客观上怎么看是不是犯罪了？我在讲路加福音第3章《活在真实的历史中》这篇讲道的时候就提过，什么是客观？神就是客观。神是这个宇宙中唯一绝对的、自存的、客观的，其他都不是。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以客观上是不是犯罪，就是神说是不是犯罪。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那么神说什么是犯罪？违背神的命令就是犯罪（约翰一书3:4）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那神命令要你干什么？神命令你要行善（诗篇37:27）。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那什么是善？我们一起来翻到弥迦书6:8：“世人哪！耶和华已指示你何为善。他向你所要的是什么呢？只要你行公义，好怜悯，存谦卑的心，与你的神同行。”")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("所以什么是善行？第一，必须是在“与神同行”，也就是说，你做一个事情在动机上，必须是为了神。第二，你必须要“存谦卑的心”，就是说你心态是谦卑的，而不是高傲的，觉得我自己有能耐，我比某某人更好。第三，你必须要“行公义、好怜悯”，就是对带着恩慈去对待人，并且你做的事情，要符合公义，也就是行为本身不能违背神的律法。你为了荣耀神、带着谦卑的心、为了某个人的益处，恩慈地去对他说谎，这不是善，因为你没有行公义。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("大家懂了吗？所以一个客观的善行，必须同时符合这三个条件：目的上为了荣耀神；心态上谦卑；行为上公义，并且如果你这个行为针对某个人，那么是要为了他的益处。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("那大家想一想，你们的一言一行，满足这个善的标准吗？上次一个姐妹说到她最近有去参加一个合作设计项目，请问你当时是与神同行、为了荣耀神吗？另外有个姐妹分享说她最近在照顾她的姥姥、照顾家人，这个时候时候你是存着谦卑的心吗？有个弟兄说最近总是与女朋友争吵、怄气，请问你这是行公义、好怜悯吗？我们每个人都想一想，你自己每一件事，都是为了神、存谦卑的心、符合神的律法、为别人的益处吗？")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果连你们都这样，那么那些不认识神的人，客观上可能无罪吗？绝不可能。他们每一个动作，都是在犯罪，因为不说别的，这个目的要件，就满足不了。连神都不认识，或者都不认为有神存在，遑论什么与神同行、出于荣耀神的目的了！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("客观上是这样了。那么主观上呢？你承不承认，你做出某个行为，缺乏了这三个要素中的任何一个，都不是善。不是善那是什么？是罪。你是否对你会做这样的事感到厌恶、恶心、难过、痛苦、后悔？无数不认识主的人，主观上都不会承认，也不会为此感到厌恶，他们会觉得这很正常啊。无数自称为基督徒的人，也是这样。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("你主观上不认为自己有罪，主观上不会对罪厌恶，那么当然你就不会去寻求耶稣的赦免，耶稣对你而言就没有意义。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("但是，真正的基督徒，客观上有罪，没有错，和所有人一样；主观上却会承认他们有罪、会对自己的罪感到厌恶、沮丧。所以他们会来到耶稣面前，就像那些跟随耶稣、与耶稣一同坐席的税吏、暴徒、妓女会来到耶稣面前一样，因为他有赦罪的权柄！他对他们有意义！")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("这些是耶稣所召的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他来不是召义人悔改。不过神从天上观看，有没有义人呢？很可惜，没有义人，连一个都没有。有的只是那些自以为义、主观上不承认自己犯罪、掩耳盗铃的人。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("他来是召罪人悔改。就像那个麻风病人、那个瘫子，相信耶稣这位弥赛亚有权柄来医治他们一样，这些罪人相信耶稣这位弥撒亚有权柄来赦免他们。他们认自己的罪、厌恶自己的罪，因此会俯伏在主面前，求他说：“主若肯，必能叫我赦免了。”而耶稣这时候会伸出他的手，触摸他们的心，说“我肯，你的罪赦了吧”。因为他是有怜悯的。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("弟兄姐妹们，耶稣有赦罪的权柄。他赦免那些寻求他的人。这些人中，包括你吗？这取决于，当你的行为不是为神而做、不是存谦卑的心、不是行公义、好怜悯时，你承不承认这是犯罪？你是不是对此感到懊悔、感到厌恶，你讨厌这样的自己，因此你想要改。你想要在生活中做每一件事情中，都“行公义、好怜悯、存谦卑的心，与神同行”，并且努力去行出这种意愿，在学习中、工作中、在项目中、在宿舍里、在家里，在遇到的每一个人、每一件事中，去努力行出这种意愿。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你是这样的人，那么耶稣是为你而来的。神把他的儿子赐给你，也把他所创造的万物一同白白地赐给了你。")])],1),t._v(" "),v("p",[v("font",{attrs:{size:"5"}},[t._v("如果你不是这样的人，你想要的是耶稣医治你的疾病、解决你的工作、和睦你的家庭、富强你的国家，那对不起，耶稣不是为你而来的。他说我来，不是为这些，我来，是召罪人悔改的。")])],1)])}),[],!1,null,null,null);s.default=e.exports}}]);